"use strict";
const $=s=>document.querySelector(s);
const main=$("#main");
const STORE_KEY="little-flute-garden-v1";
function savedRead(){try{const x=JSON.parse(localStorage.getItem(STORE_KEY)||"{}");return{done:Array.isArray(x.done)?[...new Set(x.done.filter(n=>Number.isInteger(n)&&n>=1&&n<=LESSONS.length))]:[],checks:Array.isArray(x.checks)?x.checks.filter(n=>Number.isInteger(n)&&n>=0&&n<4):[],muted:x.muted===true,composition:Array.isArray(x.composition)?x.composition.filter(n=>(n===null||Object.hasOwn(NOTES,n))).slice(0,8):[]}}catch{return{done:[],checks:[],muted:false,composition:[]}}}
let saved=savedRead(),audioCtx,oscillators=[],audioTimers=[],audioToken=0,toastTimer,game={type:"staff",index:0,found:0,answered:false,target:"B4"};
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(saved))}catch{toast("浏览器暂时不能保存进度，仍然可以继续学习。")}}
function toast(text){$("#toast").textContent=text;$("#toast").classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("#toast").classList.remove("visible"),3400)}
function stopSound(){audioToken++;audioTimers.forEach(clearTimeout);audioTimers=[];oscillators.forEach(o=>{try{o.stop()}catch{}});oscillators=[];if("speechSynthesis" in window)speechSynthesis.cancel();document.querySelectorAll(".music-note-active").forEach(e=>e.classList.remove("music-note-active"));document.querySelectorAll(".audio-playing").forEach(e=>e.classList.remove("audio-playing"));document.querySelectorAll(".beat-dot.on").forEach(e=>e.classList.remove("on"));}
async function ensureAudio(){if(saved.muted){toast("声音现在关着。点右上角“打开声音”就能听见。");return false}const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){toast("这个浏览器暂不支持示范声音，可以继续看图练习。");return false}try{audioCtx=audioCtx||new Audio();if(audioCtx.state!=="running")await audioCtx.resume();return audioCtx.state==="running"}catch{toast("声音暂时没有打开，请再点一次播放。");return false}}
function tone(note,time,duration,volume=.16){if(note===null)return;voice({start:0,duration,gate:1,parts:[{n:note,offset:0,duration,volume}]},time)}
async function playSequence(notes,{durations,bpm=64,onNote,onEnd,button}={}){stopSound();const token=audioToken;if(!await ensureAudio()||token!==audioToken)return;const now=audioCtx.currentTime+.08;let elapsed=0;if(button)button.classList.add("audio-playing");notes.forEach((n,i)=>{const length=durations?.[i]||60/bpm*.72;tone(n,now+elapsed,length);if(onNote)audioTimers.push(setTimeout(()=>{if(token===audioToken)onNote(i)},elapsed*1000+80));elapsed+=length+(durations?.[i]?.toString()? .20:60/bpm*.28)});audioTimers.push(setTimeout(()=>{if(token!==audioToken)return;document.querySelectorAll(".audio-playing").forEach(e=>e.classList.remove("audio-playing"));document.querySelectorAll(".music-note-active").forEach(e=>e.classList.remove("music-note-active"));onEnd?.()},elapsed*1000+150))}
function playNote(note){if(!Object.hasOwn(NOTES,note))return;playSequence([note])}
function updateSoundButton(){const b=$("#sound-toggle");b.textContent=saved.muted?"♫ 打开声音":"♫ 声音开着";b.setAttribute("aria-pressed",String(saved.muted));b.setAttribute("aria-label",saved.muted?"打开示范声音":"关闭示范声音")}
function speak(text){stopSound();if(saved.muted){toast("先打开右上角的声音，就能听朗读。");return}if(!("speechSynthesis" in window)){toast("这个浏览器没有朗读功能，请和家人一起读。");return}const u=new SpeechSynthesisUtterance(text);u.lang="zh-CN";u.rate=.82;const v=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith("zh"));if(v)u.voice=v;u.onerror=e=>{if(e.error!=="interrupted"&&e.error!=="canceled")toast("朗读暂时不可用，可以请家人读给你听。")};speechSynthesis.speak(u)}
function nextLesson(){return LESSONS.find(l=>!saved.done.includes(l.id))?.id||LESSONS.length}
function progress(){return '<div class="progress-strip"><p>🌱 <strong>每一点尝试，都在长大</strong>　已经探索 '+saved.done.length+' 节微课</p><div class="progress-track" role="progressbar" aria-label="已经探索的课程" aria-valuenow="'+saved.done.length+'" aria-valuemin="0" aria-valuemax="48"><span style="width:'+saved.done.length/LESSONS.length*100+'%"></span></div><span class="progress-caption">'+saved.done.length+' / 48 片小叶子</span></div>'}
function unitCard(i,expanded=false){const u=COURSE_UNITS[i],done=u.lessons.filter(n=>saved.done.includes(n)).length;return '<article class="unit-card"><a href="#lesson/'+(u.lessons.find(n=>!saved.done.includes(n))||u.lessons[0])+'" aria-label="进入'+u.title+'"><div class="unit-art"><span class="unit-num">单元 '+String(i+1).padStart(2,'0')+'</span><span class="unit-tag">'+u.tag+'</span>'+unitArt(u)+'</div><div class="unit-body"><h3>'+u.title+'</h3><p>'+u.subtitle+'</p><div class="card-meta"><span>4 节微课 · 每次约 5—10 分钟</span><span class="circle-go" aria-hidden="true">↗</span></div></div></a>'+(expanded?'<div class="lesson-list">'+u.lessons.map(n=>{const l=LESSONS[n-1];return '<a class="lesson-link '+(saved.done.includes(n)?"done":"")+'" href="#lesson/'+n+'"><span>'+(saved.done.includes(n)?"✓":n)+'</span><span>'+l.title+'</span><span class="duration">'+l.duration+'</span></a>'}).join("")+'</div>':"")+'</article>'}
function heading(eyebrow,title,desc){return '<div class="page-head"><span class="eyebrow">'+eyebrow+'</span><h1>'+title+'</h1><p>'+desc+'</p></div>'}
function homePage(){const next=nextLesson(),l=LESSONS[next-1];return '<div class="intro-line"><div><h1>你好，小音乐家 <span style="font-size:.65em">☀</span></h1><p>今天，让我们和长笛一起，发现一个新声音。</p></div><span class="season">一点好奇 · 一点练习 · 一点成长</span></div><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><span class="pill">✦　12 个单元 · 48 节图文微课</span><h2 id="hero-title">小小的长笛，<br>大大的音乐世界。</h2><p>听一听，看一看，轻轻吹一吹。<br>从第一个声音，到自己的小小音乐会。</p><a class="button" href="#lesson/'+next+'">'+(saved.done.length?"继续我的旅程":"开始第一课")+' <span>→</span></a><span class="time">◷ '+l.duration+'，就能有新发现</span></div><div class="hero-art">'+ART.hero()+'<span class="art-caption">LET THE LITTLE MUSIC GROW</span></div></section><div class="quick-row"><a class="quick-card" href="#play"><span class="quick-icon">♫</span><span><strong>和音符玩一会儿</strong><small>听声音，找朋友</small></span><span class="quick-arrow">↗</span></a><a class="quick-card" href="#songs"><span class="quick-icon">▤</span><span><strong>我的第一段音乐</strong><small>慢慢听，慢慢吹</small></span><span class="quick-arrow">↗</span></a><a class="quick-card" href="#parents"><span class="quick-icon">♡</span><span><strong>陪孩子一起长大</strong><small>给爸爸妈妈的陪练小贴士</small></span><span class="quick-arrow">↗</span></a></div><section><div class="section-title"><div><h2>从这里，一步一步出发</h2><p>先认识长笛，再找到声音，最后认识小音符。</p></div><a href="#map" class="text-link">看看整张地图 →</a></div><div class="unit-grid">'+[0,1,2].map(i=>unitCard(i)).join("")+'</div></section>'+progress()}
function mapPage(){return heading("LEARNING MAP · 课程地图","48 个小发现，一步一步长大","12 个单元都可以打开。一次一小课，也可以只听、只拍、先休息；准备好了再往前走。")+'<div class="stage-links">'+["认识长笛 · 1—12","音符与节奏 · 13—28","音乐的表达 · 29—40","变化与分享 · 41—48"].map((t,i)=>'<button class="button secondary small" data-stage="'+[0,3,7,10][i]+'">'+t+'</button>').join("")+'</div>'+progress()+'<div class="unit-grid full-map">'+COURSE_UNITS.map((_,i)=>'<div id="unit-'+i+'">'+unitCard(i,true)+'</div>').join("")+'</div>'}
function lessonPicture(l){if(l.note)return drawStaff([l.note],{interactive:true});if(l.score)return drawScore(l.score);if(l.kind==="melody")return drawStaff(l.demo,{interactive:true});return ART[l.kind]?.()||ART.listen()}
function lessonPage(id){const l=LESSONS[id-1];if(!l)return '<div class="error-panel"><h1>这节课还没准备好</h1><p>我们先回到课程地图看看吧。</p><a class="button" href="#map">回到课程地图</a></div>';const done=saved.done.includes(id);return '<a class="back" href="#map">← 回到课程地图</a><div class="lesson-header"><div><span class="eyebrow">单元 '+(l.unit+1)+' · 第 '+id+' 节微课 · '+l.duration+'</span><h1>'+l.title+'</h1><p>今天的小目标：'+l.goal+'</p></div><button class="button secondary small" data-read="'+id+'">◖ 读给我听</button></div><div class="lesson-layout"><article class="lesson-panel '+(id===45?'hide-note-labels':'')+'"><div class="lesson-illustration">'+lessonPicture(l)+'</div><div class="lesson-content">'+(l.prereq?'<p class="prereq">🌱 '+l.prereq+'</p>':'')+'<p class="child-sentence">'+l.say+'</p>'+lessonConcept(l.diagram)+l.steps.map((s,i)=>'<div class="step-row"><span class="step-badge">'+(i+1)+'</span><span>'+s+'</span></div>').join("")+lessonExtras(l)+(l.demo?'<div class="action-row"><button class="button light" data-demo="'+id+'">▶ 听示范</button><button class="button secondary" data-stop>■ 停一下</button></div><p class="audio-caption">电子示范音 · 用来听音高与长短，真实吹奏请跟随老师示范。</p>':"")+'<section class="practice-card"><h3>✦ '+l.practice+'</h3><p>'+l.task+'</p><div class="check-options">'+l.choices.map((c,i)=>'<button class="option-button" data-answer="'+i+'" data-lesson="'+id+'">'+c+'</button>').join("")+'</div><div class="feedback" id="lesson-feedback" aria-live="polite">想一想，也可以再看一遍上面的图。</div></section><div class="lesson-navigation">'+(id>1?'<a class="button secondary" href="#lesson/'+(id-1)+'">← 上一课</a>':'<a class="button secondary" href="#home">← 回到首页</a>')+'<button class="button" data-complete="'+id+'">'+(done?"再试过一次啦":"我试过啦")+' →</button></div></div></article><aside class="lesson-aside">'+(l.note?'<section class="side-card"><h3>'+noteLabel(l.note)+' 的指法小卡</h3>'+drawFingering(l.note)+'<p>圆点表示按下。此图按左右手分组，不是镜像动作图。具体型号请老师确认。</p></section>':"")+'<section class="side-card"><h3>♡ 给陪练的大人</h3><p>'+l.parent+'</p><h3>今天，留意这一点就好</h3><p>'+l.check+'</p></section><section class="side-card"><h3>这一站的小脚印</h3>'+COURSE_UNITS[l.unit].lessons.map(n=>'<a class="lesson-link '+(saved.done.includes(n)?"done":"")+'" href="#lesson/'+n+'" '+(n===id?'aria-current="step"':"")+'><span>'+(saved.done.includes(n)?"✓":n)+'</span>'+LESSONS[n-1].title+'</a>').join("")+'<p>“试过”记录一次探索，不代表动作已经掌握。熟练度由孩子、家长和老师一起观察。</p></section></aside></div>'}
function playgroundPage(){const notes=activeNotes();return heading("NOTE PLAYGROUND · 音符游乐场","和今天学的音符交朋友","先选一组熟悉的音。慢慢听、慢慢找，不需要一次记住所有朋友。")+groupPicker('group',activeGroup)+'<section class="note-lab"><div class="lab-header"><div><h2>五线谱上的小房子</h2><p>点音符，听声音；线和间从下面数起。</p></div><button class="button light small" data-demo-notes>▶ 听这一组</button></div><div class="lab-body"><div class="staff-wrap">'+drawStaff(notes,{interactive:true})+'</div><div class="note-choices">'+notes.map(n=>'<button class="note-key" data-note="'+n+'">'+noteLabel(n)+'<small>'+NOTES[n].position+'</small></button>').join('')+'</div><p class="lab-caption">这一组的音：'+notes.join(' · ')+'。数字标明音区，C5 比 B4 高一小步。</p></div></section><div class="section-title"><div><h2>选一个小游戏</h2><p>不用计时，答错了也可以再试。</p></div></div><div class="game-tabs" role="group" aria-label="选择小游戏">'+[['staff','音符捉迷藏'],['ear','听音找朋友'],['rhythm','拍拍小火车']].map(([t,n])=>'<button data-game="'+t+'" class="'+(game.type===t?'active':'')+'" aria-pressed="'+(game.type===t)+'">'+n+'</button>').join('')+'</div><div id="game-container">'+gameHTML()+'</div><div class="hint">电子音只示范音高与节奏。真实音色、口型和吐音，跟着老师慢慢找。</div><div class="section-title"><div><h2>手指也来认识一下</h2><p>先看图、做指法，再短短吹一吹。</p></div></div><div class="finger-grid">'+notes.map(n=>'<article class="finger-card"><div><h3>'+noteLabel(n)+'</h3><p>'+n+'</p><button class="button small light" data-note="'+n+'">▶ 听音</button><p><a href="#lesson/'+NOTES[n].lesson+'">去这一课 →</a></p></div>'+drawFingering(n)+'</article>').join('')+'</div><p class="local-note">常见波姆体系指法，左拇指用 B 本位键。右拇指支撑，左小指放开。D4、D5 的右小指离键，B♭4 使用 1+1 指法。具体儿童型号请老师核对。</p>'}
function gameHTML(){if(game.type==='rhythm'){const p=RHYTHM_PATTERNS[rhythmIndex];return '<section class="game-card"><span class="pill">脚步均匀 · 安静也数拍</span><h2 style="margin-top:16px">拍拍小火车</h2><div class="game-tabs pattern-tabs">'+RHYTHM_PATTERNS.map((p,i)=>'<button data-pattern="'+i+'" class="'+(i===rhythmIndex?'active':'')+'">'+p.title+'</button>').join('')+'</div>'+drawScore(rhythmScore())+'<p>先听示范，再用拍手模仿；休止符那里安静一下。</p><div class="beat-dots">'+Array.from({length:p.meter||4},(_,i)=>'<span class="beat-dot" data-beat="'+i+'">'+(i+1)+'</span>').join('')+'</div><div class="game-controls"><button class="button" data-beats>▶ 听节奏</button><button class="button secondary" data-tap>拍拍手 · '+(game.taps||0)+'</button><button class="button secondary" data-stop>■ 停一下</button></div><div class="game-feedback" aria-live="polite" id="game-feedback">点按只记录尝试，不评判准不准。用耳朵和家人一起比较。</div></section>'}const ear=game.type==='ear';return '<section class="game-card"><span class="pill">'+(ear?'先听声音，再找朋友':'看看谱位，找到朋友')+'</span><h2 style="margin-top:15px">'+(ear?'你听见了哪位朋友？':'这个音符是谁？')+'</h2>'+(ear?'<div style="margin:28px"><button class="button" data-hear>▶ 听神秘音符</button></div><p>可以先回到上面的音符卡，比较这一组的声音。</p>':'<div class="staff-wrap">'+drawStaff([game.target],{labels:false})+'</div>')+'<div class="note-choices">'+activeNotes().map(n=>'<button class="note-key" data-guess="'+n+'">'+noteLabel(n)+'<small>'+n+'</small></button>').join('')+'</div><div class="game-feedback" id="game-feedback" aria-live="polite">慢慢想，可以试不止一次。</div><div class="game-controls"><button class="button secondary small" data-game-next>换一个朋友 →</button></div><div class="game-count">已经认识了 '+game.found+' 次小音符</div></section>'}
function songCard(s){if(s.compose)return composerHTML();return '<article class="song-card" data-song-card="'+s.id+'"><span class="pill">'+(s.score?'单元 '+(s.unit+1)+' · 原创练习':'起步 · 音序练习')+'</span><h2>'+s.title+'</h2><p>'+s.subtitle+'</p><div class="song-score">'+(s.score?drawScore(s.score):drawStaff(s.notes,{interactive:true}))+'</div><p>'+s.tip+'</p><label class="speed-label">练习速度 <input type="range" min="40" max="90" value="60" step="5" data-speed="'+s.id+'" aria-label="'+s.title+'的练习速度"><span id="speed-'+s.id+'">60</span> 拍/分</label><div class="action-row"><button class="button small" data-song="'+s.id+'">▶ 听完整旋律</button><button class="button secondary small" data-song="'+s.id+'" data-phrase>听前一句</button><button class="button secondary small" data-stop>■ 停一下</button></div><p class="audio-caption">电子音高与节奏示范 · 可分句吹奏，按标记和休止自然换气。</p></article>'}
function songsPage(){return heading("MY LITTLE MELODIES · 我的曲谱盒","把小小的声音，连成音乐","从三个音到两首八小节作品。挑今天学过的曲子，先看谱，再分句练。")+'<div class="stage-links">'+['全部','起步 · 单元1—3','音符与节奏 · 单元4—7','表达与读谱 · 单元8—11','小小音乐会'].map((t,i)=>'<button class="button secondary small '+(songFilter===i?'selected':'')+'" data-song-filter="'+i+'">'+t+'</button>').join('')+'</div><div class="songs-grid">'+SONGS.filter(s=>!s.compose&&(songFilter===0||songFilter===1&&!s.score||songFilter===2&&s.unit>=3&&s.unit<=6||songFilter===3&&s.unit>=7&&s.unit<=10||songFilter===4&&s.unit===11)).map(songCard).join('')+'</div>'+composerHTML()+'<div class="hint">这些短曲为本教程原创练习。可以打印当前曲谱；速度可调，随时停下。先把身体和声音练舒服，再增加长度。</div>'}
function parentsPage(){const checks=["已请老师确认弯头朝向、口型和持笛支点","谱架与座椅合适，孩子双脚有支撑","了解具体乐器的组装与弯管清洁方法","愿意每次只观察和反馈一个重点"];return heading("GROWN-UPS CORNER · 家长陪练角","陪她发现音乐，也陪她慢慢来","这是一套日常启蒙与复习工具。12 个单元、48 节微课均可学习，技术动作请与老师的指导保持一致。")+'<div class="parent-grid"><section class="parent-card"><h2>开始之前，准备这四件事</h2>'+checks.map((c,i)=>'<label class="parent-check"><input type="checkbox" data-parent-check="'+i+'" '+(saved.checks.includes(i)?"checked":"")+'><span>'+c+'</span></label>').join("")+'<p class="local-note">勾选仅记录在当前设备，不代表网站已核验动作。</p></section><section class="parent-card"><h2>一次轻松的陪练</h2><ol><li>听一个短示范，问她发现了什么。</li><li>看看图，拍一拍或做静默指法。</li><li>短短吹几次，中间放下乐器休息。</li><li>说出一个具体进步，结束在愿意再试的时候。</li></ol><p>起初约 5—8 分钟，逐渐增加到 10—15 分钟，含听、唱和休息。不是连续吹奏的时长要求。</p></section><section class="parent-card"><h2>遇到这些情况</h2><details open><summary>一直只有气声，怎么办？</summary><p>先休息，回到笛头短尝试。请老师检查下唇与吹孔位置、气流方向及乐器，不让孩子靠猛吹解决。找声音可以花几次课。</p></details><details><summary>手臂累、肩膀耸起来了？</summary><p>先放下长笛。改做听辨、拍手或读谱；请老师调整弯头和持笛支点。疼痛或头晕时停止吹奏。</p></details><details><summary>认谱比吹奏快，或反过来？</summary><p>很正常。两条线可以分别推进。识谱熟练不等于口型已经掌握，也不需要等吹得完美才开始听辨。</p></details><details><summary>点了播放或朗读，没有声音？</summary><p>先检查右上角是否静音，以及设备音量。朗读依赖浏览器的中文语音；不支持时可以由家长朗读，图文仍可使用。</p></details></section><section class="parent-card"><h2>怎么知道她在进步？</h2><ul><li>能听出今天学的声音区别。</li><li>能在较少提醒下找到谱位或指法。</li><li>身体较放松，愿意分句再试一次。</li></ul><p>“你在安静的地方等到了下一拍。”这样的具体反馈，比一次纠正很多地方更容易理解。</p><p>页面的“小叶子”代表尝试记录，不是考试成绩。不设倒计时、排行榜或连续打卡惩罚。</p></section><section class="parent-card"><h2>关于声音、图示与指法</h2><p>声音为电子合成示范，用于音高与节奏。它不替代老师真实的长笛音色、口型或吐音示范。所有插图为概念示意，尚未经过她的授课老师核对。</p><p>高音谱表中的 B4 在第三线、A4 在第二间、G4 在第二线。指法按常见波姆体系绘制；左拇指使用 B 本位音键。D4 与 D5 的右小指放开，D5 的左食指也放开；降 B 使用 1+1 指法。具体儿童型号以老师指导为准。</p><p><a href="https://www.phyllislouke.com/wp-content/uploads/2015/08/Flute-101-Sample-Pages-from-Presser.pdf" target="_blank" rel="noopener" class="text-link">参考：Flute 101 入门样章 ↗</a><br><a href="https://www.yamaha.com/en/musical_instrument_guide/common/images/flute/fingering.pdf" target="_blank" rel="noopener" class="text-link">参考：Yamaha 长笛指法表 ↗</a></p></section><section class="parent-card"><h2>我们的学习记录</h2><p>已经探索 <strong>'+saved.done.length+' / 48</strong> 节微课。进度、陪练准备和自编旋律只保存在当前浏览器中。</p><p>不需要填写孩子的姓名，不使用麦克风，也不上传声音。更换设备或清除浏览器数据后，记录不会自动同步。</p><a class="button secondary" href="#map">看看课程记录 →</a><p class="local-note">每个单元可以重复几次。48 课不是 48 天的进度要求；技术与读谱可以按孩子状态分别推进。</p></section></div>'}
function render(){stopSound();const route=location.hash.slice(1)||"home";let tab=route.split("/")[0],title={home:"今天学什么",map:"课程地图",play:"音符游乐场",songs:"我的曲谱盒",parents:"家长陪练角",lesson:"微课时间"}[tab]||"今天学什么";if(tab==="lesson")main.innerHTML=lessonPage(Number(route.split("/")[1]));else main.innerHTML=({home:homePage,map:mapPage,play:playgroundPage,songs:songsPage,parents:parentsPage}[tab]||homePage)();$("#page-label").textContent=title;document.title=title+" · 小小长笛家";document.querySelectorAll("[data-nav]").forEach(a=>{const active=a.dataset.nav===(tab==="lesson"?"map":tab);a.classList.toggle("active",active);if(active)a.setAttribute("aria-current","page");else a.removeAttribute("aria-current")});window.scrollTo(0,0);updateSoundButton()}
function refreshGame(){stopSound();$("#game-container").innerHTML=gameHTML();document.querySelectorAll("[data-game]").forEach(b=>{b.classList.toggle("active",b.dataset.game===game.type);b.setAttribute("aria-pressed",String(b.dataset.game===game.type))})}
function refreshComposition(){const e=$('#composition-staff');if(e)e.innerHTML=compositionView();const c=$('#composition-count');if(c)c.textContent=saved.composition.length+' / 8 拍';}
document.addEventListener("click",e=>{const b=e.target.closest("button,[data-note]");if(!b)return;
if(b.id==="sound-toggle"){saved.muted=!saved.muted;stopSound();persist();updateSoundButton();return}
if(b.matches("[data-stop]")){stopSound();return}
if(b.dataset.note){playNote(b.dataset.note);return}
if(b.dataset.read){const l=LESSONS[Number(b.dataset.read)-1];if(l)speak(l.title+"。"+l.say+"。"+l.steps.join("。"));return}
if(b.dataset.demo){const l=LESSONS[Number(b.dataset.demo)-1];if(l?.demo)playSequence(l.demo,{durations:l.durations,button:b});return}
if(b.matches("[data-demo-notes]")){playSequence(activeNotes(),{button:b});return}
if(b.dataset.lesson){const l=LESSONS[Number(b.dataset.lesson)-1],answer=Number(b.dataset.answer),correct=l.answer==="any"||answer===l.answer;const fb=$("#lesson-feedback");fb.textContent=correct?l.feedback:"再看一看上面的图或听一次示范，想好了再试。";if(correct){document.querySelectorAll("[data-answer]").forEach(x=>x.classList.remove("selected"));b.classList.add("selected")}return}
if(b.dataset.complete){const id=Number(b.dataset.complete);if(!saved.done.includes(id)){saved.done.push(id);persist()}toast(saved.done.length===LESSONS.length?"48 课都留下脚印啦！可以继续重玩最喜欢的一课。":id===LESSONS.length?"音乐会这一课也留下脚印啦！回地图看看其他小发现。":"收下一片小叶子。随时可以回来再试。");location.hash=id<LESSONS.length?"lesson/"+(id+1):"map";return}
if(b.dataset.unit){const i=Number(b.dataset.unit),u=COURSE_UNITS[i];$("#dialog-body").innerHTML='<span class="eyebrow">后续课程计划 · 单元 '+(i+1)+'</span><h2 id="dialog-title" style="margin-top:16px">'+u.title+'</h2><p>'+u.subtitle+'</p><ul>'+u.goals.map(g=>'<li>'+g+'</li>').join("")+'</ul><p>这个单元尚未开放。可以先在已开放的课程里，把声音、姿势和三个音符练熟。</p><a class="button" href="#map" data-close-dialog>回到已开放课程</a>';$("#unit-dialog").showModal();return}
if(b.classList.contains("dialog-close")){$("#unit-dialog").close();return}
if(b.dataset.game){game.type=b.dataset.game;game.answered=false;game.taps=0;refreshGame();return}
if(b.matches("[data-hear]")){playSequence([game.target],{button:b});return}
if(b.dataset.guess){if(game.answered)return;if(b.dataset.guess===game.target){game.found++;game.answered=true;$("#game-feedback").textContent="找到啦，是 "+noteLabel(game.target)+"！可以再听一次，然后换个朋友。";b.classList.add("selected");document.querySelector(".game-count").textContent="已经认识了 "+game.found+" 次小音符";playNote(game.target)}else{$("#game-feedback").textContent=game.type==="staff"?"从下面数线和间，再看看音符旁有没有升降号。":"可以回到上面的音符卡，比较这一组声音，再试一次。"}return}
if(b.matches("[data-game-next]")){game.index=(game.index+1)%activeNotes().length;game.target=activeNotes()[game.index];game.answered=false;refreshGame();return}
if(b.matches('[data-beats]')){const sc=rhythmScore();playScore(sc,{bpm:70,button:b,container:b.closest('.game-card'),onTick:i=>document.querySelectorAll('.beat-dot').forEach((d,j)=>d.classList.toggle('on',i%sc.meter===j)),visualPulse:true});return}
if(b.matches('[data-tap]')){game.taps=(game.taps||0)+1;const meter=RHYTHM_PATTERNS[rhythmIndex].meter||4;document.querySelectorAll('.beat-dot').forEach((d,j)=>d.classList.toggle('on',(game.taps-1)%meter===j));b.textContent='拍拍手 · '+game.taps;return}
if(b.dataset.song){const s=SONGS.find(s=>s.id===b.dataset.song),card=b.closest('[data-song-card]'),bpm=Number(card.querySelector('input').value);if(s.score){const sc=SCORES[s.score],phrase=b.hasAttribute('data-phrase')?{...sc,bars:sc.bars.slice(0,2),repeat:false,slurs:sc.slurs?.filter(x=>x.bar<2)}:sc;playScore(phrase,{bpm,button:b,container:card})}else{const notes=b.hasAttribute('data-phrase')?s.notes.slice(0,s.phrase):s.notes;playSequence(notes,{bpm,button:b,onNote:i=>card.querySelectorAll('.staff-note').forEach((n,j)=>n.classList.toggle('music-note-active',j===i))})}return}
if(b.dataset.compose){if(saved.composition.length>=8){toast('两间小房子已经装满 8 拍啦。先听听，或撤回一拍。');return}const n=b.dataset.compose==='rest'?null:b.dataset.compose;saved.composition.push(n);persist();refreshComposition();if(n)playNote(n);else stopSound();return}
if(b.matches('[data-play-composition]')){if(!saved.composition.length){toast('先放几个音或休止，编一段小音乐吧。');return}playScore(compositionScore(),{button:b,container:$('#composition-staff')});return}
if(b.matches("[data-undo-composition]")){stopSound();saved.composition.pop();persist();refreshComposition();return}
if(b.matches("[data-clear-composition]")){stopSound();saved.composition=[];persist();refreshComposition();return}
});
document.addEventListener("click",e=>{if(e.target.closest("[data-close-dialog]"))$("#unit-dialog").close();if(e.target.closest(".skip")){e.preventDefault();main.focus();main.scrollIntoView({block:"start"})}});
document.addEventListener("keydown",e=>{const n=e.target.closest(".staff-note[role=button]");if(n&&(e.key==="Enter"||e.key===" ")){e.preventDefault();playNote(n.dataset.note)}});
document.addEventListener("input",e=>{if(e.target.matches("[data-speed]")){stopSound();$("#speed-"+e.target.dataset.speed).textContent=e.target.value}});
document.addEventListener("change",e=>{if(e.target.matches("[data-parent-check]")){const i=Number(e.target.dataset.parentCheck);saved.checks=saved.checks.filter(x=>x!==i);if(e.target.checked)saved.checks.push(i);persist()}});
$("#unit-dialog").addEventListener("click",e=>{if(e.target===$("#unit-dialog")){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
window.addEventListener("hashchange",()=>{render();main.focus({preventScroll:true})});
document.addEventListener("visibilitychange",()=>{if(document.hidden)stopSound()});
window.addEventListener("pagehide",stopSound);

let activeGroup='first',composeGroup='first',rhythmIndex=0,songFilter=0;
function activeNotes(){return NOTE_GROUPS.find(g=>g.id===activeGroup).notes}
function groupPicker(kind,value){return '<div class="game-tabs group-picker" role="group" aria-label="选择音符组">'+NOTE_GROUPS.map(g=>'<button data-'+kind+'="'+g.id+'" class="'+(g.id===value?'active':'')+'" aria-pressed="'+(g.id===value)+'">'+g.title+'</button>').join('')+'</div>'}
function unitArt(u){return ART[u.art]?ART[u.art]():drawStaff(SCORES[u.score].bars[0].filter(e=>e.n).slice(0,3).map(e=>e.n),{labels:false})}
function rhythmScore(){const p=RHYTHM_PATTERNS[rhythmIndex];return {meter:p.meter||4,bars:[p.beats.map((b,i)=>N(p.rests?.includes(i)?null:'G4',b))]}}
function compositionScore(){const notes=[...saved.composition];while(notes.length<8)notes.push(null);return {meter:4,bars:[notes.slice(0,4).map(n=>N(n)),notes.slice(4).map(n=>N(n))]}}
function compositionView(){return drawScore(compositionScore())+'<p class="local-note">'+(saved.composition.length<8?'还没填写的位置暂用一拍休止占位；继续点音符即可填入。':'两小节都装满了，可以听听，再试着演奏。')+'</p>'}
function composerHTML(){return '<section class="song-card composer"><span class="pill">原创小作曲家 · 两小节 4/4</span><h2>写给今天的自己</h2><p>一个音或一次安静，占一拍。选自己熟悉的一组，写满八拍。</p><div id="compose-picker">'+groupPicker('compose-group',composeGroup)+'</div><div id="compose-keys">'+composerKeys()+'</div><p id="composition-count" class="composition-count">'+saved.composition.length+' / 8 拍</p><div id="composition-staff">'+compositionView()+'</div><div class="action-row"><button class="button small" data-play-composition>▶ 听我的音乐</button><button class="button secondary small" data-stop>■ 停一下</button><button class="button secondary small" data-undo-composition>撤回一拍</button><button class="button secondary small" data-clear-composition>重新编一段</button></div><p>旋律保存在当前浏览器。空白位置会作为休止播放，继续填写即可替换。</p></section>'}
function composerKeys(){return '<div class="note-choices">'+NOTE_GROUPS.find(g=>g.id===composeGroup).notes.map(n=>'<button class="note-key" data-compose="'+n+'">'+noteLabel(n)+'<small>'+n+'</small></button>').join('')+'<button class="note-key rest-key" data-compose="rest">休止<small>安静一拍</small></button></div>'}
function scoreControls(id,label='听这段音乐'){return '<button class="button light" data-score="'+id+'">▶ '+label+'</button>'}
function lessonExtras(l){if(!l.score)return '';let h=l.note?'<div class="exercise-score">'+drawScore(l.score)+'</div>':'';h+='<div class="action-row">'+scoreControls(l.score)+'<button class="button secondary small" data-toggle-labels aria-pressed="'+(l.id===45)+'">'+(l.id===45?'显示音名':'藏起音名')+'</button><button class="button secondary" data-stop>■ 停一下</button></div><p class="audio-caption">电子示范音 · 用来听音高、时值与连接，不替代真实长笛的技术示范。</p>';if(l.compare)h+='<div class="comparison-scores">'+l.compare.map(([label,id])=>'<details><summary>'+label+'</summary>'+drawScore(id)+'<div class="action-row">'+scoreControls(id,label)+'<button class="button secondary small" data-stop>■ 停一下</button></div></details>').join('')+'</div>';if(l.tool==='compose')h+=composerHTML();if(l.tool==='duet')h+='<section class="ensemble-card"><h3>一起出发的小搭档</h3><p>四拍预备 → 四小节合奏。起初每分钟 60 拍。</p><div class="action-row"><button class="button small" data-duet="both">▶ 旋律与节拍</button><button class="button secondary small" data-duet="pulse">▶ 只听搭档节拍</button><button class="button secondary small" data-stop>■ 停一下</button></div><p id="count-in" aria-live="polite">先放松肩膀，准备好再点播放。</p></section>';if(l.tool==='concert')h+='<div class="hint"><strong>给家人的音乐邀请</strong><p>① 先说曲名　② 舒服地吹一首　③ 放下长笛休息　④ 再分享一首　⑤ 说一个自己的进步。</p><a class="text-link" href="#songs">到曲谱盒选曲 →</a></div>';return h}
function voice(group,base){const time=base+group.start,last=group.parts.at(-1),end=time+group.duration-Math.min(.06,last.duration*(1-group.gate));[1,2,3].forEach((harmonic,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain(),weight=[1,.12,.025][i];o.type='sine';group.parts.forEach((p,j)=>{const t=time+p.offset,level=p.volume*weight;o.frequency.setValueAtTime(noteFrequency(p.n)*harmonic,t);if(j===0){g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(level,t+.025)}else{g.gain.linearRampToValueAtTime(level,t+.025)}});g.gain.setValueAtTime(last.volume*weight,Math.max(time+.03,end-.045));g.gain.linearRampToValueAtTime(0,end);o.connect(g);g.connect(audioCtx.destination);o.start(time);o.stop(end+.01);o.onended=()=>{o.disconnect();g.disconnect()};oscillators.push(o)})}
function tick(time,accent){const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=accent?1000:740;g.gain.setValueAtTime(.08,time);g.gain.exponentialRampToValueAtTime(.001,time+.05);o.connect(g);g.connect(audioCtx.destination);o.start(time);o.stop(time+.06);o.onended=()=>{o.disconnect();g.disconnect()};oscillators.push(o)}
async function playScore(score,{bpm,button,container=main,countIn=0,pulse=false,pulseOnly=false,visualPulse=false,onTick}={}){stopSound();const token=audioToken;if(!await ensureAudio()||token!==audioToken)return;const p=compilePerformance(score,{bpm,countIn,pulse}),base=audioCtx.currentTime+.08;if(button)button.classList.add('audio-playing');if(!pulseOnly)p.events.forEach(g=>voice(g,base));p.ticks.forEach(t=>tick(base+t.start,t.accent));p.highlights.forEach(h=>audioTimers.push(setTimeout(()=>{if(token!==audioToken)return;container.querySelectorAll('.score-event').forEach(n=>n.classList.toggle('music-note-active',Number(n.dataset.event)===h.index));},80+h.start*1000)));if(countIn){const label=$('#count-in');for(let i=0;i<countIn;i++)audioTimers.push(setTimeout(()=>{if(label&&token===audioToken)label.textContent='预备 · '+(i+1)},80+i*p.spb*1000));audioTimers.push(setTimeout(()=>{if(label&&token===audioToken)label.textContent='一起开始！跟着稳定的脚步。'},80+countIn*p.spb*1000))}if(visualPulse)for(let i=0;i<p.totalBeats;i++)audioTimers.push(setTimeout(()=>{if(token===audioToken)onTick?.(i)},80+i*p.spb*1000));audioTimers.push(setTimeout(()=>{if(token!==audioToken)return;stopSound();const label=$('#count-in');if(label)label.textContent='一起结束啦。放下长笛，休息一下。'},p.duration*1000+120))}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-toggle-labels')){const panel=b.closest('.lesson-panel');const hidden=panel.classList.toggle('hide-note-labels');b.textContent=hidden?'显示音名':'藏起音名';b.setAttribute('aria-pressed',String(hidden));return}if(b.dataset.stage!==undefined){$('#unit-'+b.dataset.stage)?.scrollIntoView({behavior:'smooth',block:'start'});return}if(b.dataset.score){const container=b.closest('details')||b.closest('.lesson-panel');playScore(b.dataset.score,{button:b,container});return}if(b.dataset.duet){playScore('duet',{bpm:60,button:b,container:b.closest('.lesson-panel'),countIn:4,pulse:true,pulseOnly:b.dataset.duet==='pulse'});return}if(b.dataset.group){activeGroup=b.dataset.group;game.target=activeNotes()[0];game.index=0;game.answered=false;render();return}if(b.dataset.composeGroup){composeGroup=b.dataset.composeGroup;$('#compose-picker').innerHTML=groupPicker('compose-group',composeGroup);$('#compose-keys').innerHTML=composerKeys();return}if(b.dataset.pattern!==undefined){rhythmIndex=Number(b.dataset.pattern);game.taps=0;refreshGame();return}if(b.dataset.songFilter!==undefined){songFilter=Number(b.dataset.songFilter);render();return}});
render();

